extractor.verification_response:
{
  "algorithm": "Black Box String Hasher",
  "function": function(input) {
    // Convert input to binary
    const binary = input.split("").reduce((acc, char) => acc + char.charCodeAt(0), "");

    // Rotate the binary by 5 bits
    const rotated = binary.substring(0, 4) + binary.substring(4);

    // XOR the rotated binary with the original binary
    const result = parseInt(binary, 2) ^ parseInt(rotated, 2);

    // Output the result as text
    return result.toString();
  }
}

